use super::prelude::*;

/// The chip's `Relic.counter` holds two flags. C# `LostHpInPreviousTurn`
/// asks for a damage entry stamped with the player's previous `TurnNumber`
/// (EmotionChip.cs, `CombatHistoryEntry.HappenedLastPlayerTurn`), and that
/// number only goes up when the enemy side hands back to the player
/// (CombatManager.cs `IncrementTurnNumber`). A hit during a turn's own start,
/// before the chip's check, is that turn's, not the last one's.
///
/// [`LAST_TURN`]: a hit stamped with the previous turn number (read at turn
/// start). [`THIS_TURN`]: a hit stamped with the current one.
const LAST_TURN: i32 = 0b01;
const THIS_TURN: i32 = 0b10;

fn arm_this_turn(state: &mut CombatState) {
    if let Some(r) = state
        .relics
        .iter_mut()
        .find(|r| !r.is_melted && r.kind == crate::RelicKind::EmotionChip)
    {
        r.counter |= THIS_TURN;
    }
}

/// C# `PlayerCombatState.IncrementTurnNumber`: the current turn's hits become
/// the last turn's, and the turn before's drop out. Called where the enemy
/// side hands back to the player (not before turn 1, which starts at 1).
pub fn on_player_turn_number_increment(state: &mut CombatState) {
    if let Some(r) = state
        .relics
        .iter_mut()
        .find(|r| !r.is_melted && r.kind == crate::RelicKind::EmotionChip)
    {
        r.counter = i32::from(r.counter & THIS_TURN != 0);
    }
}

/// `EmotionChip.after_damage_received`: a hit that cost HP arms the chip for
/// the next turn (the damage entry is stamped with this turn's number).
pub(crate) fn on_after_damage_received_emotion_chip(
    state: &mut CombatState,
    ctx: &crate::hooks::DamageCtx,
    damage: i32,
) -> EffectResult {
    if !player_owns_relic(state, crate::RelicKind::EmotionChip) {
        return EffectResult::NotImplemented;
    }
    if !matches!(ctx.target, crate::hooks::CreatureRef::Player) {
        return EffectResult::NotImplemented;
    }
    if damage <= 0 {
        return EffectResult::NotImplemented;
    }
    arm_this_turn(state);
    EffectResult::Resolved
}

/// `EmotionChip.after_side_turn_start` — on player turn start, if a hit was
/// taken last turn ([`LAST_TURN`]), fire every orb's passive. Mirrors Python
/// `EmotionChip.after_side_turn_start` (`rare.py::EmotionChip`,
/// pool=DEFECT, hook channel `after_side_turn_start`).
/// `AfterPlayerTurnStart` entry for [`on_after_side_turn_start_emotion_chip`].
/// C# `EmotionChip.LostHpInPreviousTurn` is "any `DamageReceivedEntry` on the
/// owner last player turn with `!Result.WasFullyBlocked`"
/// (EmotionChip.cs:14, both builds), not "lost HP": `CreatureCmd.Damage`
/// records the entry for every hit while combat is in progress and not ending
/// (CreatureCmd.cs:294-299) — a killing blow too (it is recorded before
/// `AfterDamageReceived` is skipped), and a hit that nothing blocked even if
/// Buffer or Intangible took its HP loss to 0 (`WasFullyBlocked` needs
/// `blocked > 0 || Block > 0`, CreatureCmd.cs:274). The relic's
/// `AfterDamageReceived` arm only sees hits that cost HP and did not kill, so
/// each player damage chokepoint reports its entry here (loadout Defect
/// v0.107.1 2033). `recorded` is "combat in progress and not ending" read
/// BEFORE the hit's HP loss, which is when C# has not yet flagged the ending.
pub(crate) fn note_player_damage_entry(
    state: &mut CombatState,
    recorded: bool,
    was_fully_blocked: bool,
) {
    if !recorded || was_fully_blocked {
        return;
    }
    arm_this_turn(state);
}

fn on_after_player_turn_start_emotion_chip(state: &mut CombatState) -> EffectResult {
    on_after_side_turn_start_emotion_chip(state, Side::Player)
}

pub(crate) fn on_after_side_turn_start_emotion_chip(
    state: &mut CombatState,
    side: Side,
) -> EffectResult {
    if side != Side::Player {
        return EffectResult::NotImplemented;
    }
    if !player_owns_relic(state, crate::RelicKind::EmotionChip) {
        return EffectResult::NotImplemented;
    }
    let triggered = {
        let r = state
            .relics
            .iter_mut()
            .find(|r| !r.is_melted && r.kind == crate::RelicKind::EmotionChip);
        match r {
            Some(r) if r.counter & LAST_TURN != 0 => {
                r.counter &= !LAST_TURN;
                true
            }
            _ => false,
        }
    };
    if !triggered {
        return EffectResult::NotImplemented;
    }
    trigger_every_orb_passive(state);
    EffectResult::Resolved
}

/// EmotionChip orb walk: each channeled orb's passive, in queue order.
///
/// v0.111.0 `EmotionChip.AfterPlayerTurnStart` passes
/// `countAffectedByHooks: true` (decomp `EmotionChip.cs:54`), which routes
/// `OrbCmd.Passive` through the new `OrbModel.TriggerPassive`
/// (`OrbModel.cs:246-261`):
///
/// [decompiled C# omitted — see the cited path]
///
/// The only `ModifyOrbPassiveTriggerCount` listener is GoldPlatedCables:
/// `+1` for `OrbQueue.Orbs[0]` (`GoldPlatedCables.cs`). v0.107.1 called
/// `orb.Passive` directly, so Cables never doubled an EmotionChip trigger.
///
/// Every orb kind fires, Plasma's `+1 energy` included — `PlasmaOrb.Passive`
/// is `GainEnergy(PassiveVal)` in both builds (v0.107.1 `EmotionChip.cs:52-56`
/// calls `OrbCmd.Passive` on every orb). The turn-end
/// [`crate::orbs::passive_tick`] skips Plasma, so it can't be reused here
/// (GH #806).
fn trigger_every_orb_passive(state: &mut CombatState) {
    let filled: smallvec::SmallVec<[usize; 10]> = state
        .player
        .orbs
        .slots
        .iter()
        .enumerate()
        .filter(|(_, o)| !o.is_empty())
        .map(|(i, _)| i)
        .collect();
    let cables = state.game_version >= crate::GameVersion::V0_111_0
        && player_owns_relic(state, crate::RelicKind::GoldPlatedCables);
    for (n, idx) in filled.into_iter().enumerate() {
        let count = if n == 0 && cables { 2 } else { 1 };
        for _ in 0..count {
            crate::orbs::trigger_orb_passive_at(state, idx);
        }
    }
}

/// `EmotionChip.after_combat_end` — clear the HP-loss counter so it
/// doesn't carry across combats.
pub(crate) fn on_after_combat_end_emotion_chip(state: &mut CombatState) -> EffectResult {
    let Some(r) = state
        .relics
        .iter_mut()
        .find(|r| !r.is_melted && r.kind == crate::RelicKind::EmotionChip)
    else {
        return EffectResult::NotImplemented;
    };
    r.counter = 0;
    EffectResult::Resolved
}

pub(crate) fn install() {
    register_after_damage_received(
        RelicId::EmotionChip,
        on_after_damage_received_emotion_chip as AfterDamageReceivedFn,
    );
    // C# `EmotionChip` overrides `AfterPlayerTurnStart` (both builds), so it rides
    // that equip-ordered relic walk, not the later `AfterSideTurnStart` walk:
    // its order against ChoicesParadox / GamblingChip / RoyalPoison is the
    // player's relic order (GH #1054).
    register_after_player_turn_start(
        RelicId::EmotionChip,
        on_after_player_turn_start_emotion_chip as AfterPlayerTurnStartFn,
    );
    register_owned_after_combat_end(
        RelicId::EmotionChip,
        crate::RelicKind::EmotionChip,
        on_after_combat_end_emotion_chip as AfterCombatEndFn,
    );
}
